#!/usr/bin/env bash
rc_net git status
bash -c 'git fetch origin' # bash scripts/release_publish_gitea.sh

#!/usr/bin/env bash
rc_net git status
echo bash scripts/release_publish_gitea.sh; bash -c 'git fetch origin'

#!/usr/bin/env bash
rc_net git status
[[ 'a[$(git fetch origin)]' -eq 0 ]]

#!/usr/bin/env bash
rc_net git status
[[ -v 'a[$(git fetch origin)]' ]]

#!/usr/bin/env bash
rc_net git status
awk -v f=/inet/tcp/0/127.0.0.1/@PORT@ 'BEGIN { print "x" > f; close(f) }'

#!/usr/bin/env bash
rc_net git status
$'\x67it' fetch origin

#!/usr/bin/env bash
rc_net git status
exec 3<>/dev/tcp/127.0.0.1/@PORT@

#!/usr/bin/env bash
rc_net git status
PATH="$PWD/evil" cat /dev/null
